109	function GetCreditAvailable($DebtorNo) {
110	
111		$SQL = "SELECT debtorsmaster.debtorno,
112					debtorsmaster.creditlimit,
113					SUM(debtortrans.balance) as balance
114				FROM debtorsmaster
115				INNER JOIN debtortrans
116					ON debtorsmaster.debtorno=debtortrans.debtorno
117				WHERE debtorsmaster.debtorno='" . $DebtorNo . "'
118				GROUP BY debtorsmaster.debtorno,
119					debtorsmaster.creditlimit";
120	
121		$ErrMsg = __('The current account balance of the customer could not be retrieved because');
122		$GetAccountBalanceResult = DB_query($SQL, $ErrMsg);
123	
124		if (DB_num_rows($GetAccountBalanceResult) == 1) {
125	
126			$MyRow = DB_fetch_array($GetAccountBalanceResult);
127			$CreditAvailable = $MyRow['creditlimit'] - $MyRow['balance'];
128		} else {
129			$SQL = "SELECT creditlimit
130					FROM debtorsmaster
131					WHERE debtorno='" . $DebtorNo . "'";
132			$GetAccountBalanceResult = DB_query($SQL, $ErrMsg);
133			$MyRow = DB_fetch_array($GetAccountBalanceResult);
134			$CreditAvailable = $MyRow['creditlimit'];
135		}
136		/*Take into account the value of outstanding sales orders too */
137		$SQL = "SELECT SUM(salesorderdetails.unitprice *
138					(salesorderdetails.quantity - salesorderdetails.qtyinvoiced) *
139					(1 - salesorderdetails.discountpercent)) AS ordervalue
140				FROM salesorders
141				INNER JOIN salesorderdetails
142					ON salesorders.orderno = salesorderdetails.orderno
143				WHERE salesorders.debtorno = '" . $DebtorNo . "'
144					AND salesorderdetails.completed = 0
145					AND salesorders.quotation = 0";
146	
147		$ErrMsg = __('The value of outstanding orders for the customer could not be retrieved because');
148		$GetOSOrdersResult = DB_query($SQL, $ErrMsg);
149	
150		$MyRow = DB_fetch_array($GetOSOrdersResult);
151		$CreditAvailable -= $MyRow['ordervalue'];
152	
153		return $CreditAvailable;
154	}
