INSERT INTO `dunningstages` VALUES (1,'Polite reminder',30,'Payment reminder - account {AccountNo}','Dear {CustomerName},

Our records show that the invoices listed below on your account {AccountNo} are now past their due date. The overdue amount is {Currency} {OverdueAmount}.

{InvoiceList}

If you have already sent payment please accept our thanks and disregard this reminder. Otherwise we would be grateful for payment at your earliest convenience.

Yours sincerely,

Credit Control
{CompanyName}',0),(2,'Second reminder',45,'Second reminder - overdue account {AccountNo}','Dear {CustomerName},

We wrote to you recently about the overdue invoices on your account {AccountNo}. We have not yet received payment and the overdue amount is now {Currency} {OverdueAmount}.

{InvoiceList}

Please arrange payment immediately or contact our credit control department if there is a reason this amount cannot be paid.

Yours sincerely,

Credit Control
{CompanyName}',0),(3,'Final notice',60,'FINAL NOTICE - account {AccountNo}','Dear {CustomerName},

Despite our previous reminders the invoices below on your account {AccountNo} remain unpaid. The overdue amount is {Currency} {OverdueAmount}.

{InvoiceList}

Unless payment is received within 7 days your account will be placed on stop and no further orders will be supplied. Interest and late payment fees will also be charged on the overdue balance in accordance with our terms of trade.

Yours sincerely,

Credit Control
{CompanyName}',1);
